      body: jsonEncode(body.toJson()),
      contentType: 'application/json',
      authenticated: true,
    );
    final Object? decoded = jsonDecode(utf8.decode(response.bodyBytes));
    return Subtask.fromJson(decoded as Map<String, Object?>);
  }

