  /// Sends one request and throws [AppApiException] for any
  /// status outside 2xx and 3xx.
  Future<http.Response> _send(
    String method,
    String path, {
    Map<String, String?> query = const {},
    Object? body,
    String? contentType,
    Map<String, String>? fields,
    List<http.MultipartFile>? files,
    required bool authenticated,
  }) async {
    final base = baseUri.path.endsWith('/')
        ? baseUri.path.substring(0, baseUri.path.length - 1)
        : baseUri.path;
    final present = {
      for (final e in query.entries)
        if (e.value != null) e.key: e.value!,
    };
    final uri = baseUri.replace(
      path: '$base$path',
      queryParameters: present.isEmpty ? null : present,
    );
    final headers = <String, String>{
      'accept': 'application/json',
      if (authenticated && bearerToken != null)
        'authorization': 'Bearer $bearerToken'
      else if (authenticated && apiKey != null)
        'x-api-key': apiKey!,
    };
    final http.BaseRequest request;
    if (fields != null || files != null) {
      request = http.MultipartRequest(method, uri)
        ..fields.addAll(fields ?? const {})
        ..files.addAll(files ?? const []);
    } else {
      final plain = http.Request(method, uri);
      if (body is String) {
        plain.body = body;
      } else if (body is List<int>) {
        plain.bodyBytes = body;
      } else if (body != null) {
        plain.body = jsonEncode(body);
      }
      request = plain;
    }
    request.headers.addAll(headers);
    if (contentType != null && body != null) {
      request.headers['content-type'] = contentType;
    }
    final response = await http.Response.fromStream(await _http.send(request));
    if (response.statusCode < 200 || response.statusCode >= 400) {
      throw AppApiException.of(response);
    }
    return response;
  }
